/**
 * Decides whether every named role under `agents/` declares a toolset that fits what the role IS.
 *
 * WHY THIS EXISTS (`delegated-role-toolset-narrower-than-its-contract`). Two SDD agents in a row delivered
 * PARTIAL because their role definition withheld the Bash tool: a role asked to MEASURE cannot, without
 * execution, produce anything but hypotheses wearing the costume of findings. The fix was to add Bash to
 * the planning roles, and the files carrying that fix are regenerated by `gentle-ai sync`, so the fix can
 * be undone silently at any update. This module reads the declared toolsets and refuses a role whose
 * toolset no longer fits its profile, and its selftest runs over the real `agents/` on every landing.
 *
 * THE DECISION. Every role file declares a capability PROFILE in `ROLE_POLICY`, and each profile in
 * `PROFILES` states both directions of what the role is: what it must be able to REACH and what it must
 * NOT be able to reach. An `executor` measures or verifies, so it must reach a command runner; a
 * `blind-reviewer` judges what it is shown, so it must read and must not change, run or fetch anything.
 * No role is exempt: a profile with nothing to demand would be an exemption in disguise, and the selftest
 * refuses it. A role file that no profile claims is a finding, so a new role forces the question instead of
 * slipping past it. `tools: []` means every tool: it satisfies a must and breaks a must-not, unless
 * `disallowedTools:` closes the tool. A tool counts only as a whole token: `BashOutput` reads shell output
 * and runs nothing. A tool a profile needs may not be named in `disallowedTools:` at all.
 *
 * NO REGEX (M5): `split`, `trim`, `startsWith`, `includes` on literals.
 *
 * @es Decide si cada rol nombrado de `agents/` declara un conjunto de herramientas que encaja con lo que el
 * rol ES. Dos agentes SDD seguidos entregaron PARCIAL porque su rol no tenía Bash; el arreglo vive en
 * ficheros que `gentle-ai sync` regenera, así que podía deshacerse en silencio en cualquier actualización.
 * Este módulo lee los conjuntos declarados y rechaza un rol cuyo conjunto ya no encaja con su perfil.
 * Cada rol declara un PERFIL de capacidad en `ROLE_POLICY` y cada perfil de `PROFILES` dice los dos
 * sentidos: lo que el rol DEBE poder alcanzar y lo que NO DEBE poder alcanzar. Un `executor` mide o
 * verifica, así que alcanza un ejecutor de órdenes; un `blind-reviewer` juzga lo que se le muestra, así que lee y no
 * cambia, ejecuta ni descarga nada. Ningún rol está exento: un perfil sin nada que exigir sería una
 * exención disfrazada y el selftest lo rechaza. Un fichero de rol que ningún perfil reclama es un
 * hallazgo. `tools: []` significa todas las herramientas: cumple un DEBE y rompe un NO DEBE, salvo que
 * `disallowedTools:` cierre la herramienta. Una herramienta cuenta solo como token entero: `BashOutput`
 * lee salida y no ejecuta nada. Una herramienta que el perfil necesita no puede ir en `disallowedTools:`.
 */

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';

/** The tools that run a command. @es Las herramientas que ejecutan una orden. */
export const EXECUTION_TOOLS = ['Bash', 'PowerShell'];

/**
 * What each kind of role IS. `requires` is a list of groups and the role must reach at least one tool of
 * every group; `forbids` lists tools the role must not reach.
 * @es Lo que ES cada tipo de rol. `requires` es una lista de grupos y el rol debe alcanzar al menos una
 * herramienta de cada grupo; `forbids` lista herramientas que el rol no debe alcanzar.
 */
export const PROFILES = {
  executor: { requires: [EXECUTION_TOOLS], forbids: [] },
  'blind-reviewer': { requires: [['Read']], forbids: [...EXECUTION_TOOLS, 'Write', 'Edit', 'NotebookEdit', 'WebFetch', 'WebSearch'] },
};

/**
 * Every role file and the profile it declares. gentle-ai v4 (ODD, 2026-10-11) retired the SDD phase roles and
 * their research role; ODD delegates to generic workers, so only the review and judgment-day roles remain.
 * @es Cada fichero de rol y el perfil que declara. gentle-ai v4 (ODD, 2026-10-11) retiró los roles de fase SDD
 * y su rol de investigación; ODD delega en workers genéricos, así que solo quedan los de revisión y judgment-day.
 */
export const ROLE_POLICY = {
  'jd-fix-agent': 'executor',
  'review-risk': 'executor',
  'review-resilience': 'executor',
  'review-readability': 'executor',
  'review-reliability': 'executor',
  'review-refuter': 'executor',
  'jd-judge-a': 'blind-reviewer',
  'jd-judge-b': 'blind-reviewer',
};

/** The role files present in `agentsDirectory`, as role names. @es Los ficheros de rol presentes, como nombres de rol. */
export function rolesIn(agentsDirectory) {
  return readdirSync(agentsDirectory).filter((name) => name.endsWith('.md')).map((name) => name.slice(0, -'.md'.length)).sort();
}

/** The frontmatter lines of a role file, or `undefined` when it has none. @es Las líneas de frontmatter, o `undefined` si no hay. */
function frontmatterOf(text) {
  const lines = text.split('\n').map((line) => line.trimEnd());
  if (lines[0] !== '---') return undefined;

  const closing = lines.indexOf('---', 1);

  return closing === -1 ? undefined : lines.slice(1, closing);
}

/** The value of `key:` in the frontmatter, or `undefined` when the line is absent. @es El valor de `key:`, o `undefined` si falta. */
function valueOf(frontmatter, key) {
  const line = frontmatter.find((candidate) => candidate.startsWith(`${key}:`));

  return line === undefined ? undefined : line.slice(key.length + 1).trim();
}

/** The tokens of a comma list. @es Los tokens de una lista separada por comas. */
function tokensOf(value) {
  return value.split(',').map((token) => token.trim()).filter((token) => token.length > 0);
}

/**
 * What one role file declares: `all` (`tools: []`), the `declared` tools and the `disallowed` ones, or a
 * `problem` naming why it cannot be read.
 * @es Qué declara un fichero de rol: `all` (`tools: []`), las herramientas `declared` y las `disallowed`, o un `problem`.
 */
export function declarationOf(text) {
  const frontmatter = frontmatterOf(text);
  if (frontmatter === undefined) return { problem: 'has no frontmatter, so its tools cannot be read @es no tiene frontmatter, así que no se leen sus herramientas' };

  const tools = valueOf(frontmatter, 'tools');
  if (tools === undefined) return { problem: 'declares no `tools:` line, so its capability is unverifiable @es no declara `tools:`, así que su capacidad no es verificable' };

  const all = tools === '[]';

  return { all, declared: all ? [] : tokensOf(tools), disallowed: tokensOf(valueOf(frontmatter, 'disallowedTools') ?? '') };
}

/** Whether the declaration lets the role use `tool`. @es Si la declaración deja al rol usar `tool`. */
function reaches(declaration, tool) {
  return !declaration.disallowed.includes(tool) && (declaration.all || declaration.declared.includes(tool));
}

/**
 * The problems of one declaration against one profile, in both directions: a needed group nobody reaches or
 * that `disallowedTools:` blocks, and the forbidden tools it does reach.
 * @es Los problemas de una declaración frente a un perfil, en los dos sentidos.
 */
function profileProblems(declaration, profile, profileName) {
  const problems = [];

  for (const group of profile.requires) {
    const blocked = group.filter((tool) => declaration.disallowed.includes(tool));
    if (blocked.length > 0) problems.push(`blocks ${blocked.join(', ')} through \`disallowedTools:\` although a ${profileName} needs ${group.join(' / ')} @es bloquea ${blocked.join(', ')} con \`disallowedTools:\` aunque un ${profileName} necesita ${group.join(' / ')}`);
    else if (!group.some((tool) => reaches(declaration, tool))) problems.push(`is a ${profileName} and must reach ${group.join(' / ')} but declares none @es es un ${profileName} y debe alcanzar ${group.join(' / ')} pero no declara ninguna`);
  }

  const leaked = profile.forbids.filter((tool) => reaches(declaration, tool));
  if (leaked.length > 0) problems.push(`is a ${profileName} and must not reach ${leaked.join(', ')} but can @es es un ${profileName} y no debe alcanzar ${leaked.join(', ')} pero puede`);

  return problems;
}

/**
 * Every role whose declared toolset does not fit its profile, and every role file nobody classified.
 * @es Cada rol cuyo conjunto declarado no encaja con su perfil, y cada fichero de rol sin clasificar.
 * @param {string} agentsDirectory
 * @param {Record<string, string>} [policy] the role to profile map @es el mapa de rol a perfil
 * @returns {{ role: string, problem: string }[]}
 */
export function toolsetGaps(agentsDirectory, policy = ROLE_POLICY) {
  if (!existsSync(agentsDirectory)) return [{ role: '(agents)', problem: `directory ${agentsDirectory} is missing @es falta el directorio ${agentsDirectory}` }];

  const present = rolesIn(agentsDirectory);
  const gaps = [];

  for (const role of present) {
    const profileName = policy[role];
    if (profileName === undefined) {
      gaps.push({ role, problem: 'is not classified in ROLE_POLICY: declare which profile it is @es no está clasificado en ROLE_POLICY: declara qué perfil es' });
      continue;
    }
    if (!Object.hasOwn(PROFILES, profileName)) {
      gaps.push({ role, problem: `names the profile ${profileName}, which PROFILES does not define @es nombra el perfil ${profileName}, que PROFILES no define` });
      continue;
    }

    const declaration = declarationOf(readFileSync(path.join(agentsDirectory, `${role}.md`), 'utf8'));
    const problems = declaration.problem === undefined ? profileProblems(declaration, PROFILES[profileName], profileName) : [declaration.problem];
    for (const problem of problems) gaps.push({ role, problem });
  }

  for (const role of Object.keys(policy)) {
    if (!present.includes(role)) gaps.push({ role, problem: 'is classified in ROLE_POLICY but its file is missing @es está clasificado en ROLE_POLICY pero falta su fichero' });
  }

  return gaps;
}
